Given a string s, find all possible ways to partition it such that every substring in the partition is a palindrome.Examples: Input:  s = "geeks"Output: [[g, e, e, k, s], [g, ee, k, s]]Explanation: [g, e, e, k, s] and [g, ee, k, s] are the only partitions of "geeks" where each substring is a palindrome.Input:  s = "abcba"Output: [[a, b, c, b, a], [a, bcb, a], [abcba]]Explanation: [a, b, c, b, a], [a, bcb, a] and [abcba] are the only partitions of "abcba" where each substring is a palindrome.Try It YourselfTable of Content[Approach 1] Using Recursion and Backtracking[Approach 2] Using Bit Manipulation[Expected Approach] Backtracking with Memoization[Approach 1] Using Recursion and BacktrackingThe main idea is to use backtracking to explore all combinations of substrings starting from each index, including a substring in the current partition only if it is a palindrome.Step-By-Step Approach:Start at index 0 of the string.Generate all substrings starting from the current index.Check if the current substring is a palindrome.If it is, add it to the current partition path.Recursively continue from the next index.If the end of the string is reached, add the current path to the result.Backtrack by removing the last added substring and try the next possibility.
            C++

    #include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <numeric>
using namespace std;

// Check if the given string is a palindrome
bool isPalindrome(string& s) {
    int i = 0, j = s.size() - 1;
    while (i < j) {
        if (s[i++] != s[j--]) 
            return false;
    }
    return true;
}

// Recursive function to find all palindromic partitions
void backtrack(int idx, string& s, vector<string>& curr,
    vector<vector<string>>& res) {

    if (idx == s.size()) {
        // Store valid partition
        res.push_back(curr); 
        return;
    }

    string temp = "";
    for (int i = idx; i < s.size(); ++i) {
        temp += s[i];
        if (isPalindrome(temp)) {
            // Choose the substring
            curr.push_back(temp);            
            // Explore further
            backtrack(i + 1, s, curr, res);  
            // Backtrack
            curr.pop_back();                 
        }
    }
}

// Return all palindromic partitions of string s
vector<vector<string>> palinParts(string& s) {
    vector<vector<string>> res;
    vector<string> curr;
    backtrack(0, s, curr, res);
    return res;
}


int main() {
    string s = "geeks";

    vector<vector<string>> res = palinParts(s);

    // Print result: one partition per line
    for (int i = 0; i < res.size(); ++i) {
        for (int j = 0; j < res[i].size(); ++j) {
            cout << res[i][j];
            if (j != res[i].size() - 1) cout << " ";
        }
        cout << "\n";
    }

    return 0;
}


